"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/components/layout/auth-provider";
import { TopBar } from "@/components/layout/TopBar";
import { AdminUser, getUsers, updateUserStatus, UserRole } from "@/services/admin";

export default function OldAdminPage() {
  const { user, isReady } = useAuth();
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [error, setError] = useState("");
  const [updatingId, setUpdatingId] = useState<number | null>(null);
  const isAdministrator = user?.role === "Administrator";

  useEffect(() => {
    if (!isReady || !isAdministrator) return;
    getUsers()
      .then(setUsers)
      .catch((caught) =>
        setError(caught instanceof Error ? caught.message : "Unable to load users.")
      );
  }, [isAdministrator, isReady]);

  function replaceUser(updated: AdminUser) {
    setUsers((current) =>
      current.map((item) => (item.id === updated.id ? updated : item))
    );
  }

  async function changeStatus(id: number, is_active: boolean) {
    try {
      setError("");
      setUpdatingId(id);
      replaceUser(await updateUserStatus(id, is_active));
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Unable to update the user status.");
    } finally {
      setUpdatingId(null);
    }
  }

  if (!isReady)
    return (
      <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
        <TopBar user={user} />
        <main className="flex-1 px-[24px] py-[32px]">
          <p className="mx-auto max-w-6xl font-data-mono text-sm text-on-surface-variant">
            LOADING USER MANAGEMENT…
          </p>
        </main>
      </div>
    );

  if (!isAdministrator)
    return (
      <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
        <TopBar user={user} />
        <main className="flex-1 px-[24px] py-[32px]">
          <section className="glass-card mx-auto max-w-2xl rounded-[24px] p-[32px]">
            <p className="font-label-caps text-label-caps tracking-widest text-danger">
              ACCESS DENIED
            </p>
            <h1 className="mt-[12px] font-display-md text-display-md">
              Administrator access is required.
            </h1>
            <p className="mt-[12px] text-sm text-on-surface-variant">
              You do not have permission to manage user accounts.
            </p>
          </section>
        </main>
      </div>
    );

  return (
    <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
      <TopBar user={user} />
      <main className="flex-1 px-[24px] py-[32px]">
        <div className="mx-auto max-w-7xl">
          <div className="flex flex-wrap items-end justify-between gap-[16px]">
            <div>
              <p className="font-label-caps text-label-caps tracking-widest text-primary">
                ADMINISTRATION
              </p>
              <h1 className="mt-[8px] font-display-md text-display-md">User Management</h1>
              <p className="mt-[8px] text-sm text-on-surface-variant">
                Manage account roles and access status.
              </p>
            </div>
          </div>
          {error && <p className="mt-[24px] text-danger">{error}</p>}
          <section className="glass-card mt-[24px] overflow-x-auto rounded-[24px] p-[24px]">
            <table className="w-full min-w-[780px] text-left text-sm">
              <thead className="border-b border-border text-on-surface-variant">
                <tr>
                  <th className="px-[12px] py-[12px] font-medium">Name</th>
                  <th className="px-[12px] py-[12px] font-medium">Email</th>
                  <th className="px-[12px] py-[12px] font-medium">Role</th>
                  <th className="px-[12px] py-[12px] font-medium">Status</th>
                  <th className="px-[12px] py-[12px] font-medium">Created</th>
                </tr>
              </thead>
              <tbody>
                {users.map((account) => {
                  const isSelf = account.id === user?.id;
                  const isUpdating = updatingId === account.id;
                  return (
                    <tr
                      className="border-b border-border/70 last:border-0"
                      key={account.id}
                    >
                      <td className="px-[12px] py-[16px] font-medium">
                        {account.full_name}
                      </td>
                      <td className="px-[12px] py-[16px] text-on-surface-variant">
                        {account.email}
                      </td>
                      <td className="px-[12px] py-[16px]">
                        <span className="font-medium text-foreground">
                          {account.role}
                        </span>
                      </td>
                      <td className="px-[12px] py-[16px]">
                        <label className="inline-flex items-center gap-[8px]">
                          <input
                            aria-label={`Active status for ${account.full_name}`}
                            checked={account.is_active}
                            disabled={isSelf || isUpdating}
                            onChange={(event) =>
                              void changeStatus(account.id, event.target.checked)
                            }
                            type="checkbox"
                          />
                          <span
                            className={account.is_active ? "text-primary" : "text-danger"}
                          >
                            {account.is_active ? "Active" : "Inactive"}
                          </span>
                        </label>
                      </td>
                      <td className="px-[12px] py-[16px] text-on-surface-variant">
                        {new Date(account.created_at).toLocaleDateString()}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {!error && !users.length && (
              <p className="py-[24px] font-data-mono text-sm text-on-surface-variant">
                NO USERS FOUND.
              </p>
            )}
          </section>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/components/layout/auth-provider";
import { TopBar } from "@/components/layout/TopBar";
import {
  AdminStats,
  AdminUser,
  getAdminStats,
  getUsers,
  deactivateUser,
  reactivateUser,
  updateUserStatus,
  UserRole,
} from "@/services/admin";
import { AdminStatsCards } from "@/components/admin/AdminStatsCards";
import { AdminUserTable } from "@/components/admin/AdminUserTable";
import { CreateOfficialModal } from "@/components/admin/CreateOfficialModal";
import { AdminConfirmDialog } from "@/components/admin/AdminConfirmDialog";

export default function AdminPage() {
  const router = useRouter();
  const { user, isReady, isAuthenticated } = useAuth();
  const isAdministrator = user?.role === "Administrator";

  const [stats, setStats] = useState<AdminStats | null>(null);
  const [statsLoading, setStatsLoading] = useState(true);

  const [users, setUsers] = useState<AdminUser[]>([]);
  const [total, setTotal] = useState(0);
  const [usersLoading, setUsersLoading] = useState(true);

  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(25);
  const [reloadKey, setReloadKey] = useState(0);

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean;
    targetUser: AdminUser | null;
    action: "deactivate" | "reactivate" | null;
  }>({ isOpen: false, targetUser: null, action: null });

  const [feedback, setFeedback] = useState<{ message: string; type: "success" | "error" } | null>(null);

  // Auth gate effect
  useEffect(() => {
    if (!isReady) return;
    if (!isAuthenticated) {
      router.push("/login");
      return;
    }
    if (!isAdministrator) {
      const timer = setTimeout(() => router.push("/"), 1000);
      return () => clearTimeout(timer);
    }
  }, [isReady, isAuthenticated, isAdministrator, router]);

  // Data fetching effect (promise callbacks avoid synchronous setState)
  useEffect(() => {
    if (!isReady || !isAdministrator) return;
    let active = true;

    getAdminStats()
      .then((data) => {
        if (active) setStats(data);
      })
      .catch(() => {})
      .finally(() => {
        if (active) setStatsLoading(false);
      });

    getUsers({
      q: search || undefined,
      role: roleFilter || undefined,
      status: statusFilter || undefined,
      limit,
      offset: (page - 1) * limit,
    })
      .then((res) => {
        if (active) {
          setUsers(res);
          setTotal(res.total);
        }
      })
      .catch((err) => {
        if (active) {
          setFeedback({
            message: err instanceof Error ? err.message : "Failed to load user accounts.",
            type: "error",
          });
        }
      })
      .finally(() => {
        if (active) setUsersLoading(false);
      });

    return () => {
      active = false;
    };
  }, [isReady, isAdministrator, search, roleFilter, statusFilter, page, limit, reloadKey]);

  // Ref guard for open-modal button
  const createBtnRef = useRef(false);
  function handleOpenCreateModal() {
    if (createBtnRef.current) return;
    createBtnRef.current = true;
    setIsCreateModalOpen(true);
    setTimeout(() => { createBtnRef.current = false; }, 200);
  }

  function handleOfficialCreated(newOfficial: AdminUser) {
    setFeedback({ message: `Official account created for ${newOfficial.email}.`, type: "success" });
    setReloadKey((k) => k + 1);
  }

  async function handleExecuteConfirmAction() {
    if (!confirmDialog.targetUser || !confirmDialog.action) return;
    const { targetUser: target, action } = confirmDialog;

    if (action === "deactivate") {
      const updated = await deactivateUser(target.id);
      setUsers((prev) => prev.map((u) => (u.id === updated.id ? updated : u)));
      setFeedback({ message: `User ${target.email} has been deactivated.`, type: "success" });
    } else {
      const updated = await reactivateUser(target.id);
      setUsers((prev) => prev.map((u) => (u.id === updated.id ? updated : u)));
      setFeedback({ message: `User ${target.email} has been reactivated.`, type: "success" });
    }
    setReloadKey((k) => k + 1);
  }

  async function handleStatusChange(userId: number, isActive: boolean) {
    try {
      const updated = await updateUserStatus(userId, isActive);
      setUsers((prev) => prev.map((u) => (u.id === updated.id ? updated : u)));
      setFeedback({ message: `User #${userId} status set to ${isActive ? "Active" : "Inactive"}`, type: "success" });
      setReloadKey((k) => k + 1);
    } catch (err) {
      setFeedback({ message: err instanceof Error ? err.message : "Failed to toggle status.", type: "error" });
    }
  }

  if (!isReady) {
    return (
      <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
        <TopBar user={user} />
        <main className="flex-1 px-[24px] py-[32px] flex items-center justify-center">
          <p className="font-data-mono text-sm text-on-surface-variant">LOADING USER MANAGEMENT…</p>
        </main>
      </div>
    );
  }

  if (!isAdministrator) {
    return (
      <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
        <TopBar user={user} />
        <main className="flex-1 px-[24px] py-[32px]">
          <section className="glass-card mx-auto max-w-2xl rounded-[24px] p-[32px]">
            <p className="font-data-mono text-[11px] font-semibold tracking-widest text-danger uppercase">
              ACCESS DENIED
            </p>
            <h1 className="mt-[12px] font-display-md text-2xl font-bold">Administrator access is required.</h1>
            <p className="mt-[12px] text-sm text-on-surface-variant">
              You do not have permission to manage user accounts. Redirecting...
            </p>
          </section>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
      <TopBar user={user} />
      <main className="flex-1 px-[24px] py-[32px]">
        <div className="mx-auto max-w-7xl">
          <div className="flex flex-wrap items-end justify-between gap-[16px]">
            <div>
              <p className="font-data-mono text-[11px] font-semibold tracking-widest text-primary uppercase">
                ADMINISTRATION // CONSOLE
              </p>
              <h1 className="mt-[8px] font-display-md text-display-md font-bold">User Management</h1>
              <p className="mt-[6px] text-sm text-on-surface-variant">
                Manage account roles, deactivate access, provision government officials, and inspect platform aggregates.
              </p>
            </div>

            <button
              type="button"
              id="open-create-official-btn"
              onClick={handleOpenCreateModal}
              className="h-[38px] px-[16px] inline-flex items-center gap-[8px] rounded-[8px] border border-primary/60 bg-primary/15 text-primary hover:bg-primary/25 font-data-mono text-[12px] font-semibold tracking-wider uppercase shadow-[0_0_15px_rgba(34,211,238,0.25)] transition-all cursor-pointer"
            >
              <span className="material-symbols-outlined text-[18px]">person_add</span>
              <span>Create Official</span>
            </button>
          </div>

          {feedback && (
            <div
              className={`mt-[20px] p-[12px] rounded-[10px] text-[13px] font-data-mono flex items-center justify-between border ${
                feedback.type === "success"
                  ? "bg-success/10 border-success/30 text-success"
                  : "bg-danger/10 border-danger/30 text-danger"
              }`}
            >
              <div className="flex items-center gap-[8px]">
                <span className="material-symbols-outlined text-[18px]">
                  {feedback.type === "success" ? "check_circle" : "error"}
                </span>
                <span>{feedback.message}</span>
              </div>
              <button
                type="button"
                onClick={() => setFeedback(null)}
                className="text-on-surface-variant hover:text-foreground p-[2px]"
              >
                <span className="material-symbols-outlined text-[16px]">close</span>
              </button>
            </div>
          )}

          <div className="mt-[24px]">
            <AdminStatsCards stats={stats} loading={statsLoading} />
          </div>

          <AdminUserTable
            users={users}
            total={total}
            page={page}
            limit={limit}
            search={search}
            roleFilter={roleFilter}
            statusFilter={statusFilter}
            currentUserId={user?.id}
            loading={usersLoading}
            onSearchChange={(val) => { setSearch(val); setPage(1); }}
            onRoleFilterChange={(val) => { setRoleFilter(val); setPage(1); }}
            onStatusFilterChange={(val) => { setStatusFilter(val); setPage(1); }}
            onPageChange={setPage}
            onLimitChange={(newLimit) => { setLimit(newLimit); setPage(1); }}
            onOpenConfirm={(target, action) => setConfirmDialog({ isOpen: true, targetUser: target, action })}
            onStatusChange={handleStatusChange}
          />
        </div>
      </main>

      <CreateOfficialModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onCreated={handleOfficialCreated}
      />

      <AdminConfirmDialog
        isOpen={confirmDialog.isOpen}
        targetUser={confirmDialog.targetUser}
        action={confirmDialog.action}
        onClose={() => setConfirmDialog({ isOpen: false, targetUser: null, action: null })}
        onConfirm={handleExecuteConfirmAction}
      />
    </div>
  );
}

"use client";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { TopBar } from "@/components/layout/TopBar";
import { ProjectCard } from "@/components/projects/ProjectCard";
import { City, getCities } from "@/services/cities";
import { getProjects, Project } from "@/services/projects";

export default function CityBrowsePage() {
  const params = useParams<{ citySlug: string }>();
  const slug = params.citySlug;
  const [city, setCity] = useState<City | null>(null);
  const [projects, setProjects] = useState<Project[]>([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getCities()
      .then((records) => setCity(records.find((record) => record.slug === slug) ?? null))
      .catch((caught) =>
        setError(caught instanceof Error ? caught.message : "Unable to load city.")
      );
  }, [slug]);

  useEffect(() => {
    setLoading(true);
    getProjects({ city: slug })
      .then(setProjects)
      .catch((caught) =>
        setError(caught instanceof Error ? caught.message : "Unable to load city records.")
      )
      .finally(() => setLoading(false));
  }, [slug]);

  return (
    <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
      <TopBar />
      <main className="flex-1 px-[24px] py-[32px]">
        <div className="mx-auto max-w-6xl">
          <header className="flex flex-wrap items-start justify-between gap-[16px]">
            <div>
              <p className="font-label-caps text-label-caps tracking-widest text-primary">
                CITY BROWSER
              </p>
              <h1 className="mt-[8px] font-display-md text-display-md">
                {city?.name ?? "City"}
              </h1>
            </div>
          </header>
          {error ? (
            error.includes("Authentication required") || error.includes("401") ? (
              <div className="mt-[24px]">
                <p className="text-on-surface">Log in to see this</p>
                <Link className="mt-[8px] inline-block font-semibold text-primary hover:underline" href="/login">
                  Log in
                </Link>
              </div>
            ) : (
              <p className="mt-[24px] text-danger">{error}</p>
            )
          ) : loading ? (
            <p className="mt-[24px] font-data-mono text-[12px] text-on-surface-variant">
              LOADING PROJECTS...
            </p>
          ) : !city ? (
            <p className="glass-card mt-[24px] rounded-xl p-[24px] text-on-surface-variant">
              This city is not currently supported. Please choose another city.
            </p>
          ) : !projects.length ? (
            <div className="glass-card mt-[24px] rounded-xl p-[24px]">
              <h2 className="font-display-md text-[22px]">No projects yet</h2>
              <p className="mt-[8px] text-sm text-on-surface-variant">
                There are no projects recorded for {city.name}.
              </p>
            </div>
          ) : (
            <div className="mt-[24px] grid gap-[16px] md:grid-cols-2 xl:grid-cols-3">
              {projects.map((project) => (
                <ProjectCard key={project.id} project={project} />
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

