"use client";

import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { ComplaintForm } from "@/components/citizen/ComplaintForm";
import { FeedbackForm } from "@/components/consultations/FeedbackForm";
import { DocumentUploadForm } from "@/components/documents/DocumentUploadForm";
import { useAuth } from "@/components/layout/auth-provider";
import { TopBar } from "@/components/layout/TopBar";
import { ProjectForm } from "@/components/projects/ProjectForm";
import { StatusBadge } from "@/components/projects/StatusBadge";
import { Complaint, createComplaint, getComplaints } from "@/services/complaints";
import { Consultation, createFeedback, getConsultations } from "@/services/consultations";
import {
  getDocumentDownloadUrl,
  getDocuments,
  PlanningDocument,
  uploadDocument,
} from "@/services/documents";
import { getProject, Project, updateProject } from "@/services/projects";

const editorRoles = ["Urban Planner", "Government Official", "Administrator"];

type RelatedState<T> = {
  records: T[];
  loading: boolean;
  unauthorized: boolean;
  error: string;
};

const initialRelated = <T,>(): RelatedState<T> => ({
  records: [],
  loading: true,
  unauthorized: false,
  error: "",
});

type TabKey = "complaints" | "consultations" | "documents";

const TAB_LABELS: Record<TabKey, string> = {
  complaints: "Complaints",
  consultations: "Consultations",
  documents: "Documents",
};

function LoginPrompt({ label }: { label: string }) {
  return (
    <p className="text-sm text-on-surface-variant">
      Log in to view {label} related to this project.{" "}
      <Link className="text-primary" href="/login">
        LOG IN
      </Link>
    </p>
  );
}

export default function ProjectDetailPage() {
  const params = useParams<{ id: string }>();
  const router = useRouter();
  const { user, isReady } = useAuth();
  const id = Number(params.id);

  const [project, setProject] = useState<Project | null>(null);
  const [editing, setEditing] = useState(false);
  const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState<TabKey>("complaints");

  const [complaints, setComplaints] = useState<RelatedState<Complaint>>(initialRelated);
  const [consultations, setConsultations] = useState<RelatedState<Consultation>>(initialRelated);
  const [documents, setDocuments] = useState<RelatedState<PlanningDocument>>(initialRelated);

  const canEdit = Boolean(user && editorRoles.includes(user.role));

  useEffect(() => {
    if (Number.isNaN(id)) {
      setError("Invalid project record.");
      return;
    }
    getProject(id)
      .then(setProject)
      .catch((caught) =>
        setError(caught instanceof Error ? caught.message : "Unable to load project."),
      );
  }, [id]);

  useEffect(() => {
    if (!project || !isReady) return;

    if (!user) {
      const prompt = { records: [], loading: false, unauthorized: true, error: "" };
      setComplaints(prompt);
      setConsultations(prompt);
      setDocuments(prompt);
      return;
    }

    function load<T>(request: () => Promise<T[]>, setter: (state: RelatedState<T>) => void) {
      request()
        .then((records) => setter({ records, loading: false, unauthorized: false, error: "" }))
        .catch((caught) => {
          const status = (caught as Error & { status?: number }).status;
          setter({
            records: [],
            loading: false,
            unauthorized: status === 401,
            error: status === 401 ? "" : caught instanceof Error ? caught.message : "Unable to load related records.",
          });
        });
    }

    load(() => getComplaints({ project_id: project.id }), setComplaints);
    load(() => getConsultations({ project_id: project.id }), setConsultations);
    load(() => getDocuments({ project_id: project.id }), setDocuments);
  }, [isReady, project, user]);

  if (error) {
    return (
      <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
        <TopBar user={user} />
        <main className="flex-1 p-[32px] text-danger">{error}</main>
      </div>
    );
  }

  if (!project) {
    return (
      <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
        <TopBar user={user} />
        <main className="flex-1 p-[32px] font-data-mono text-on-surface-variant">
          LOADING PROJECT RECORD...
        </main>
      </div>
    );
  }

  const tabCounts: Record<TabKey, number> = {
    complaints: complaints.records.length,
    consultations: consultations.records.length,
    documents: documents.records.length,
  };

  return (
    <div className="min-h-screen flex flex-col bg-surface-container-lowest text-on-surface">
      <TopBar user={user} />
      <main className="flex-1 px-[24px] py-[32px]">
        <div className="mx-auto max-w-5xl">
          <Link className="font-data-mono text-[11px] text-primary" href="/projects">
            &larr; ALL PROJECTS
          </Link>

        <article className="glass-card mt-[20px] rounded-xl p-[28px]">
          <div className="flex flex-wrap items-start justify-between gap-[16px]">
            <div>
              <p className="font-data-mono text-[11px] uppercase tracking-wider text-on-surface-variant">
                {project.category ?? "General planning"}
              </p>
              <h1 className="mt-[8px] font-display-md text-display-md">{project.title}</h1>
            </div>
            <StatusBadge status={project.status} />
          </div>

          <p className="mt-[20px] max-w-3xl leading-7 text-on-surface-variant">
            {project.description ?? "No description recorded."}
          </p>

          <div className="mt-[24px] grid gap-[12px] border-t border-white/10 pt-[20px] font-data-mono text-[11px] text-on-surface-variant sm:grid-cols-2">
            <span>CITY: {project.city ?? "Not assigned"}</span>
            <span>BUDGET: {project.budget ?? "Pending"}</span>
            <span>
              DATES: {project.start_date ?? "TBD"} &mdash; {project.end_date ?? "TBD"}
            </span>
            <span>UPDATED: {new Date(project.updated_at).toLocaleDateString()}</span>
          </div>

          {canEdit && (
            <button
              className="mt-[24px] border border-primary-container/60 px-[14px] py-[10px] font-data-mono text-[11px] text-primary"
              onClick={() => setEditing((current) => !current)}
              type="button"
            >
              {editing ? "CLOSE EDITOR" : "EDIT PROJECT"}
            </button>
          )}
        </article>

        {editing && (
          <div className="mt-[20px]">
            <ProjectForm
              initial={project}
              onSubmit={async (payload) => {
                const updated = await updateProject(project.id, payload);
                setProject(updated);
                setEditing(false);
                router.refresh();
              }}
            />
          </div>
        )}

        {/* Tab selector */}
        <div className="mt-[24px] flex flex-wrap gap-[8px] rounded-xl border border-white/10 bg-surface-bright/10 p-[6px]">
          {(Object.keys(TAB_LABELS) as TabKey[]).map((key) => (
            <button
              key={key}
              type="button"
              onClick={() => setActiveTab(key)}
              className={
                activeTab === key
                  ? "flex-1 inline-flex items-center justify-center gap-1 rounded-lg bg-primary-container/15 border border-primary-container/60 px-[16px] py-[10px] font-data-mono text-[11px] uppercase tracking-wider text-primary"
                  : "flex-1 inline-flex items-center justify-center gap-1 rounded-lg border border-transparent px-[16px] py-[10px] font-data-mono text-[11px] uppercase tracking-wider text-on-surface-variant hover:border-white/10"
              }
            >
              <span>{TAB_LABELS[key]}</span>
              {isReady && !user ? (
                <>
                  <span
                    className="material-symbols-outlined text-[13px] text-muted-foreground/70 ml-[4px]"
                    aria-hidden="true"
                  >
                    lock
                  </span>
                  <span className="sr-only">Log in required</span>
                </>
              ) : user ? (
                <span>({tabCounts[key]})</span>
              ) : null}
            </button>
          ))}
        </div>

        {/* Active tab content */}
        <div className="mt-[20px]">
          {activeTab === "complaints" && (
            <RelatedSection title="Complaints" state={complaints} unauthenticatedLabel="complaints">
              {complaints.records.map((complaint) => (
                <article className="glass-card rounded-xl p-[16px]" key={complaint.id}>
                  <div className="flex flex-wrap items-start justify-between gap-[12px]">
                    <h3 className="font-semibold text-on-surface">{complaint.subject}</h3>
                    <span className="font-data-mono text-[11px] text-primary">{complaint.status}</span>
                  </div>
                  <p className="mt-[8px] text-sm text-on-surface-variant">{complaint.description}</p>
                </article>
              ))}
              {user && (
                <ComplaintForm
                  initialProjectId={project.id}
                  projects={[project]}
                  onSubmit={async (payload) => {
                    const created = await createComplaint(payload);
                    setComplaints((current) => ({ ...current, records: [created, ...current.records] }));
                  }}
                />
              )}
            </RelatedSection>
          )}

          {activeTab === "consultations" && (
            <RelatedSection title="Consultations" state={consultations} unauthenticatedLabel="consultations">
              {consultations.records.map((consultation) => (
                <article className="glass-card rounded-xl p-[16px]" key={consultation.id}>
                  <div className="flex flex-wrap items-start justify-between gap-[12px]">
                    <div>
                      <h3 className="font-semibold text-on-surface">{consultation.title}</h3>
                      <p className="mt-[4px] font-data-mono text-[11px] text-on-surface-variant">
                        {new Date(consultation.scheduled_at).toLocaleString()} &middot;{" "}
                        {consultation.location ?? "Location to be confirmed"}
                      </p>
                    </div>
                    <span className="font-data-mono text-[11px] text-primary">{consultation.status}</span>
                  </div>
                  {user && (
                    <div className="mt-[16px]">
                      <FeedbackForm onSubmit={async (comment) => { await createFeedback(consultation.id, comment); }} />
                    </div>
                  )}
                </article>
              ))}
            </RelatedSection>
          )}

          {activeTab === "documents" && (
            <RelatedSection title="Documents" state={documents} unauthenticatedLabel="documents">
              {documents.records.map((document) => (
                <article
                  className="glass-card flex flex-wrap items-center justify-between gap-[16px] rounded-xl p-[16px]"
                  key={document.id}
                >
                  <div>
                    <h3 className="font-semibold text-on-surface">{document.title}</h3>
                    <p className="mt-[4px] text-sm text-on-surface-variant">
                      {document.original_filename} &middot; Uploaded by {document.uploaded_by_name}
                    </p>
                  </div>
                  <a
                    className="border border-primary-container/60 px-[14px] py-[10px] font-data-mono text-[11px] text-primary"
                    href={getDocumentDownloadUrl(document.id)}
                  >
                    DOWNLOAD
                  </a>
                </article>
              ))}
              {canEdit && (
                <DocumentUploadForm
                  initialProjectId={project.id}
                  projects={[project]}
                  onSubmit={async (payload) => {
                    const created = await uploadDocument(payload);
                    setDocuments((current) => ({ ...current, records: [created, ...current.records] }));
                  }}
                />
              )}
            </RelatedSection>
          )}
        </div>
      </div>
    </main>
  </div>
  );
}

function RelatedSection<T>({
  title,
  state,
  unauthenticatedLabel,
  children,
}: {
  title: string;
  state: RelatedState<T>;
  unauthenticatedLabel: string;
  children: React.ReactNode;
}) {
  return (
    <article className="glass-card rounded-xl p-[24px]">
      <h2 className="font-display-md text-[26px] text-on-surface">{title}</h2>
      <div className="mt-[16px] flex flex-col gap-[16px]">
        {state.loading ? (
          <p className="font-data-mono text-[12px] text-on-surface-variant">
            LOADING {title.toUpperCase()}...
          </p>
        ) : state.unauthorized ? (
          <LoginPrompt label={unauthenticatedLabel} />
        ) : state.error ? (
          <p className="text-danger">{state.error}</p>
        ) : state.records.length ? (
          children
        ) : (
          <p className="font-data-mono text-[12px] text-on-surface-variant">
            NO {title.toUpperCase()} ARE LINKED TO THIS PROJECT.
          </p>
        )}
        {!state.loading && !state.unauthorized && !state.error && !state.records.length ? children : null}
      </div>
    </article>
  );
}

"use client";

import { useRef } from "react";
import { AdminUser, UserRole, userRoles } from "@/services/admin";

type AdminUserTableProps = {
  users: AdminUser[];
  total: number;
  page: number;
  limit: number;
  search: string;
  roleFilter: string;
  statusFilter: string;
  currentUserId: number | undefined;
  loading: boolean;
  onSearchChange: (val: string) => void;
  onRoleFilterChange: (val: string) => void;
  onStatusFilterChange: (val: string) => void;
  onPageChange: (newPage: number) => void;
  onLimitChange: (newLimit: number) => void;
  onOpenConfirm: (user: AdminUser, action: "deactivate" | "reactivate") => void;
  onStatusChange: (userId: number, isActive: boolean) => void;
};

export function AdminUserTable({
  users,
  total,
  page,
  limit,
  search,
  roleFilter,
  statusFilter,
  currentUserId,
  loading,
  onSearchChange,
  onRoleFilterChange,
  onStatusFilterChange,
  onPageChange,
  onLimitChange,
  onOpenConfirm,
  onStatusChange,
}: AdminUserTableProps) {
  const pageNavRef = useRef(false);
  const totalPages = Math.max(1, Math.ceil(total / limit));

  function handlePageNav(delta: number) {
    if (pageNavRef.current) return;
    const target = page + delta;
    if (target < 1 || target > totalPages) return;
    pageNavRef.current = true;
    onPageChange(target);
    setTimeout(() => { pageNavRef.current = false; }, 200);
  }

  const startIdx = total === 0 ? 0 : (page - 1) * limit + 1;
  const endIdx = Math.min(total, page * limit);

  return (
    <div className="glass-card rounded-[20px] p-[24px] border border-white/10 mt-[24px]">
      {/* Search & Filters */}
      <div className="flex flex-wrap items-center justify-between gap-[16px] pb-[20px] border-b border-white/10">
        <div className="flex flex-wrap items-center gap-[12px] flex-1 min-w-[280px]">
          <div className="relative flex-1 max-w-sm">
            <span className="material-symbols-outlined absolute left-[12px] top-1/2 -translate-y-1/2 text-[18px] text-on-surface-variant/60" aria-hidden="true">
              search
            </span>
            <input
              id="search-users-input"
              type="text"
              value={search}
              onChange={(e) => onSearchChange(e.target.value)}
              placeholder="Search name, email, city..."
              className="w-full h-[38px] pl-[38px] pr-[12px] rounded-[8px] bg-surface-muted/60 border border-white/15 text-foreground font-sans text-[13px] placeholder:text-on-surface-variant/50 focus:outline-none focus:border-primary"
            />
          </div>

          <div className="w-[160px]">
            <select
              id="role-filter-select"
              value={roleFilter}
              onChange={(e) => onRoleFilterChange(e.target.value)}
              aria-label="Filter users by role"
              className="w-full h-[38px] px-[12px] rounded-[8px] bg-surface-muted/60 border border-white/15 text-foreground font-sans text-[13px] focus:outline-none focus:border-primary"
            >
              <option value="">All Roles</option>
              {userRoles.map((r) => (<option key={r} value={r}>{r}</option>))}
            </select>
          </div>

          <div className="w-[140px]">
            <select
              id="status-filter-select"
              value={statusFilter}
              onChange={(e) => onStatusFilterChange(e.target.value)}
              aria-label="Filter users by status"
              className="w-full h-[38px] px-[12px] rounded-[8px] bg-surface-muted/60 border border-white/15 text-foreground font-sans text-[13px] focus:outline-none focus:border-primary"
            >
              <option value="">All Statuses</option>
              <option value="active">Active</option>
              <option value="inactive">Inactive</option>
            </select>
          </div>
        </div>

        <div className="flex items-center gap-[8px] text-[12px] font-data-mono text-on-surface-variant">
          <span>Show:</span>
          <select
            id="page-size-select"
            value={limit}
            onChange={(e) => onLimitChange(Number(e.target.value))}
            className="h-[32px] px-[8px] rounded-[6px] bg-surface-muted/60 border border-white/15 text-foreground focus:outline-none focus:border-primary text-[12px]"
          >
            <option value={10}>10</option>
            <option value={25}>25</option>
            <option value={50}>50</option>
          </select>
        </div>
      </div>

      {/* Users Table */}
      <div className="overflow-x-auto mt-[16px]">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-white/10 text-[11px] font-data-mono uppercase tracking-wider text-on-surface-variant">
              <th className="py-[12px] px-[12px]">User</th>
              <th className="py-[12px] px-[12px]">Email</th>
              <th className="py-[12px] px-[12px]">Role</th>
              <th className="py-[12px] px-[12px]">City</th>
              <th className="py-[12px] px-[12px]">Status</th>
              <th className="py-[12px] px-[12px]">Created</th>
              <th className="py-[12px] px-[12px] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5 text-[13px]">
            {loading && users.length === 0 ? (
              <tr>
                <td colSpan={7} className="py-[32px] text-center text-on-surface-variant font-data-mono text-[12px]">
                  LOADING USER REGISTRY…
                </td>
              </tr>
            ) : users.length === 0 ? (
              <tr>
                <td colSpan={7} className="py-[32px] text-center text-on-surface-variant font-data-mono text-[12px]">
                  No matching user accounts found.
                </td>
              </tr>
            ) : (
              users.map((item) => {
                const isSelf = currentUserId === item.id;
                const displayName = item.name || item.full_name;

                return (
                  <tr key={item.id} className="hover:bg-white/[0.02] transition-colors">
                    {/* Column 0: Full Name & ID */}
                    <td className="py-[12px] px-[12px]">
                      <div className="flex items-center gap-[8px]">
                        <span className="font-semibold text-foreground">{displayName}</span>
                        {isSelf && (
                          <span className="px-[6px] py-[1px] rounded text-[10px] font-data-mono border border-primary/40 bg-primary/10 text-primary">
                            YOU
                          </span>
                        )}
                        {item.is_demo && (
                          <span className="px-[6px] py-[1px] rounded text-[10px] font-data-mono border border-white/20 bg-white/5 text-on-surface-variant">
                            DEMO
                          </span>
                        )}
                      </div>
                      <span className="text-[11px] font-data-mono text-on-surface-variant/70">ID: #{item.id}</span>
                    </td>

                    {/* Column 1: Email (Matches test_j5 td[1]) */}
                    <td className="py-[12px] px-[12px] font-data-mono text-[12px] text-foreground">
                      {item.email}
                    </td>

                    {/* Column 2: Role */}
                    <td className="py-[12px] px-[12px]">
                      <span className="inline-block px-[8px] py-[2px] rounded-[6px] bg-surface-muted/60 border border-white/10 text-[12px] font-sans font-medium text-foreground">
                        {item.role}
                      </span>
                    </td>

                    {/* Column 3: City */}
                    <td className="py-[12px] px-[12px] font-data-mono text-[12px] text-on-surface-variant capitalize">
                      {item.city || "—"}
                    </td>

                    {/* Column 4: Status (Matches test_j4 input aria-label) */}
                    <td className="py-[12px] px-[12px]">
                      <div className="flex items-center gap-[8px]">
                        <input
                          type="checkbox"
                          aria-label={`Active status for ${displayName}`}
                          checked={item.is_active}
                          disabled={isSelf}
                          onChange={(e) => onStatusChange(item.id, e.target.checked)}
                          className="h-[16px] w-[16px] accent-primary rounded cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                        />
                        <span className={`inline-block px-[8px] py-[2px] rounded-full text-[10px] font-data-mono font-medium ${
                          item.is_active
                            ? "bg-success/10 text-success border border-success/30"
                            : "bg-danger/10 text-danger border border-danger/30"
                        }`}>
                          {item.is_active ? "Active" : "Inactive"}
                        </span>
                      </div>
                    </td>

                    {/* Column 5: Created Date */}
                    <td className="py-[12px] px-[12px] font-data-mono text-[11px] text-on-surface-variant">
                      {item.created_at ? item.created_at.slice(0, 10) : "—"}
                    </td>

                    {/* Column 6: Actions */}
                    <td className="py-[12px] px-[12px] text-right">
                      {isSelf ? (
                        <span className="text-[11px] font-data-mono text-on-surface-variant/50 italic">Protected</span>
                      ) : item.is_active ? (
                        <button
                          type="button"
                          id={`deactivate-user-${item.id}-btn`}
                          onClick={() => onOpenConfirm(item, "deactivate")}
                          className="h-[28px] px-[10px] rounded-[6px] border border-danger/40 bg-danger/10 text-danger hover:bg-danger/20 font-data-mono text-[11px] font-medium transition-colors"
                        >
                          Deactivate
                        </button>
                      ) : (
                        <button
                          type="button"
                          id={`reactivate-user-${item.id}-btn`}
                          onClick={() => onOpenConfirm(item, "reactivate")}
                          className="h-[28px] px-[10px] rounded-[6px] border border-success/40 bg-success/10 text-success hover:bg-success/20 font-data-mono text-[11px] font-medium transition-colors"
                        >
                          Reactivate
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="flex flex-wrap items-center justify-between gap-[16px] pt-[16px] mt-[12px] border-t border-white/10 text-[12px] font-data-mono text-on-surface-variant">
        <div>Showing {startIdx}–{endIdx} of {total} accounts</div>
        <div className="flex items-center gap-[8px]">
          <button
            type="button"
            id="prev-page-btn"
            onClick={() => handlePageNav(-1)}
            disabled={page <= 1 || loading}
            className="h-[32px] px-[12px] rounded-[6px] border border-white/15 bg-white/5 hover:bg-white/10 text-foreground disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            Previous
          </button>
          <span>Page {page} of {totalPages}</span>
          <button
            type="button"
            id="next-page-btn"
            onClick={() => handlePageNav(1)}
            disabled={page >= totalPages || loading}
            className="h-[32px] px-[12px] rounded-[6px] border border-white/15 bg-white/5 hover:bg-white/10 text-foreground disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}

