  const [values, setValues] = useState({ title: initial?.title ?? "", description: initial?.description ?? "", status: initial?.status ?? "Proposed", category: initial?.category ?? "", city: initial?.city ?? "", budget: initial?.budget?.toString() ?? "", location_lat: initial?.location_lat?.toString() ?? "", location_lng: initial?.location_lng?.toString() ?? "", start_date: initial?.start_date ?? "", end_date: initial?.end_date ?? "" });
  const [cities, setCities] = useState<City[]>([]); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  const set = (key: keyof typeof values, value: string) => setValues((current) => ({ ...current, [key]: value }));
  useEffect(() => { getCities().then(setCities).catch((caught) => setError(caught instanceof Error ? caught.message : "Unable to load cities.")); }, []);
