  return <form className="glass-card rounded-xl p-[24px]" onSubmit={submit}><h2 className="font-display-md text-[22px] text-on-surface">Project record</h2><div className="mt-[20px] grid gap-[16px] md:grid-cols-2"><Field label="Title" value={values.title} onChange={(value) => set("title", value)} required /><Field label="Category" value={values.category} onChange={(value) => set("category", value)} /><CitySelect cities={cities} value={values.city} onChange={(value) => set("city", value)} /><label className="font-data-mono text-[11px] uppercase tracking-wider text-on-surface-variant">Status<select className="mt-[8px] w-full border border-white/15 bg-surface-container-lowest/70 px-[12px] py-[10px] text-sm text-on-surface" value={values.status} onChange={(event) => set("status", event.target.value)}>{["Proposed", "Approved", "InProgress", "Completed", "OnHold"].map((value) => <option key={value}>{value}</option>)}</select></label><Field label="Budget" type="number" value={values.budget} onChange={(value) => set("budget", value)} /><Field label="Latitude" type="number" value={values.location_lat} onChange={(value) => set("location_lat", value)} /><Field label="Longitude" type="number" value={values.location_lng} onChange={(value) => set("location_lng", value)} /><p className="font-data-mono text-[11px] leading-5 text-on-surface-variant md:col-span-2">Optional — used to place this project on the GIS map. Leave blank if the location isn't yet determined.</p><Field label="Start date" type="date" value={values.start_date} onChange={(value) => set("start_date", value)} /><Field label="End date" type="date" value={values.end_date} onChange={(value) => set("end_date", value)} /></div><label className="mt-[16px] block font-data-mono text-[11px] uppercase tracking-wider text-on-surface-variant">Description<textarea className="mt-[8px] min-h-[100px] w-full border border-white/15 bg-surface-container-lowest/70 px-[12px] py-[10px] text-sm text-on-surface" value={values.description} onChange={(event) => set("description", event.target.value)} /></label>{error && <p className="mt-[12px] text-sm text-danger">{error}</p>}<button className="mt-[20px] border border-primary-container/60 px-[16px] py-[10px] font-label-caps text-label-caps tracking-widest text-primary transition hover:bg-primary-container/10 disabled:opacity-60" disabled={saving} type="submit">{saving ? "SAVING..." : "SAVE PROJECT"}</button></form>;
}
function CitySelect({ cities, value, onChange }: { cities: City[]; value: string; onChange: (value: string) => void }) { return <label className="font-data-mono text-[11px] uppercase tracking-wider text-on-surface-variant">City<select className="mt-[8px] w-full border border-white/15 bg-surface-container-lowest/70 px-[12px] py-[10px] text-sm text-on-surface" required value={value} onChange={(event) => onChange(event.target.value)}><option value="">Select a city</option>{cities.map((city) => <option key={city.slug} value={city.slug}>{city.name}</option>)}</select></label>; }
function Field({ label, value, onChange, type = "text", required = false }: { label: string; value: string; onChange: (value: string) => void; type?: string; required?: boolean }) { return <label className="font-data-mono text-[11px] uppercase tracking-wider text-on-surface-variant">{label}<input className="mt-[8px] w-full border border-white/15 bg-surface-container-lowest/70 px-[12px] py-[10px] text-sm text-on-surface" required={required} type={type} value={value} onChange={(event) => onChange(event.target.value)} /></label>; }

